// Inbound files from the ODFI: returns (addenda 99) and notifications of change (addenda 98). The same code path
// handles files generated by the simulated bank, dropped by the SFTP adapter, or uploaded through the API, so the
// demo exercises exactly what production would run.
import { withTx } from '../db.js';
import { decrypt, encrypt } from '../crypto.js';
import { parseAchFile } from '../nacha.js';
import { NOC_CODES } from '../ach.js';
import { returnTransfer } from './transfers.js';

const TRANSACTION_CODE_TYPE = { 22: 'checking', 27: 'checking', 32: 'savings', 37: 'savings' };

/** Fields a NOC corrects, as laid out in the 29-char corrected data field. */
function parseCorrectedData(code, data) {
  const d = data.padEnd(29, ' ');
  switch (code) {
    case 'C01': return { account: d.slice(0, 17).trim() };
    case 'C02': return { routing: d.slice(0, 9).trim() };
    case 'C03': return { routing: d.slice(0, 9).trim(), account: d.slice(12, 29).trim() };
    case 'C05': return { accountType: TRANSACTION_CODE_TYPE[d.slice(0, 2)] };
    case 'C06': return { account: d.slice(0, 17).trim(), accountType: TRANSACTION_CODE_TYPE[d.slice(20, 22)] };
    case 'C07': return { routing: d.slice(0, 9).trim(), account: d.slice(9, 26).trim(), accountType: TRANSACTION_CODE_TYPE[d.slice(26, 28)] };
    default: return {};
  }
}

/** Applies a notification of change to the account behind the original entry and records every corrected field. */
async function applyNoc(client, transfer, addenda, fileName) {
  const code = addenda.changeCode;
  const fix = parseCorrectedData(code, addenda.correctedData);
  const { rows: [account] } = await client.query('SELECT * FROM bank_accounts WHERE id = $1 FOR UPDATE', [transfer.bank_account_id]);
  const changes = [];
  const sets = [];
  const params = [account.id];
  const set = (column, value) => {
    params.push(value);
    sets.push(`${column} = $${params.length}`);
  };

  if (fix.routing && /^\d{9}$/.test(fix.routing) && fix.routing !== account.routing_number) {
    changes.push({ field: 'routing_number', old: account.routing_number, new: fix.routing });
    set('routing_number', fix.routing);
  }
  if (fix.account && fix.account !== decrypt(account.account_number_enc)) {
    changes.push({ field: 'account_number', old: `••••${account.last4}`, new: `••••${fix.account.slice(-4)}` });
    set('account_number_enc', encrypt(fix.account));
    set('last4', fix.account.slice(-4));
  }
  if (fix.accountType && fix.accountType !== account.account_type) {
    changes.push({ field: 'account_type', old: account.account_type, new: fix.accountType });
    set('account_type', fix.accountType);
  }
  if (sets.length) await client.query(`UPDATE bank_accounts SET ${sets.join(', ')} WHERE id = $1`, params);

  const description = NOC_CODES[code] ?? 'Notification of change';
  for (const c of changes) {
    await client.query(
      `INSERT INTO account_changes (bank_account_id, transfer_id, change_code, description, old_value, new_value)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [account.id, transfer.id, code, `${description} (${c.field})`, c.old, c.new],
    );
  }
  await client.query('INSERT INTO transfer_events (transfer_id, status, note) VALUES ($1, $2, $3)', [
    transfer.id,
    transfer.status,
    `${code} ${description} received in ${fileName}; account data updated (${changes.map((c) => c.field).join(', ') || 'no change needed'})`,
  ]);
  return { fields: changes.map((c) => c.field) };
}

/**
 * Stores an inbound NACHA file and applies every return and NOC in it to our transfers and accounts.
 * Returns { file, errors, results }. A file that fails validation is stored as rejected and applies nothing.
 */
export async function applyInboundFile(content, { transport, fileName }) {
  const { header, batches, entries, errors, totals } = parseAchFile(content);

  return withTx(async (client) => {
    const { rows: [file] } = await client.query(
      `INSERT INTO ach_files (kind, file_id_modifier, content, batch_count, entry_count, entry_hash, total_debit_cents,
                              total_credit_cents, status, process_after, file_name, transport)
       VALUES ('return', $1, $2, $3, $4, $5, $6, $7, $8, now(), $9, $10)
       RETURNING id, kind, file_id_modifier, batch_count, entry_count, total_debit_cents, total_credit_cents, status,
                 file_name, transport, created_at`,
      [header?.fileIdModifier ?? 'A', encrypt(content), batches.length, totals.recordCount, totals.entryHash,
       totals.debitCents, totals.creditCents, errors.length ? 'rejected' : 'received', fileName, transport],
    );

    if (errors.length) {
      await client.query(`UPDATE ach_files SET processed_at = now(), bank_response = $2 WHERE id = $1`, [file.id, JSON.stringify({ errors })]);
      return { file, errors, results: [] };
    }

    const results = [];
    for (const e of entries) {
      if (!e.addenda || !['98', '99'].includes(e.addenda.typeCode)) {
        results.push({ trace: e.traceNumber, outcome: 'ignored', reason: 'entry has no return or NOC addenda' });
        continue;
      }
      const originalTrace = e.addenda.originalTraceNumber;
      const { rows: [t] } = await client.query('SELECT * FROM transfers WHERE trace_number = $1 FOR UPDATE', [originalTrace]);
      if (!t) {
        results.push({ original_trace: originalTrace, outcome: 'unmatched', reason: 'no transfer with this trace number' });
        continue;
      }
      if (e.addenda.typeCode === '99') {
        const code = e.addenda.returnReasonCode;
        if (!['submitted', 'accepted', 'settled'].includes(t.status)) {
          results.push({ original_trace: originalTrace, transfer_id: t.id, outcome: 'skipped', reason: `transfer is already ${t.status}` });
          continue;
        }
        await returnTransfer(client, t, code, `return file ${fileName}`);
        results.push({ original_trace: originalTrace, transfer_id: t.id, outcome: 'returned', code });
      } else {
        const applied = await applyNoc(client, t, e.addenda, fileName);
        results.push({ original_trace: originalTrace, transfer_id: t.id, outcome: 'noc_applied', code: e.addenda.changeCode, ...applied });
      }
    }

    await client.query(`UPDATE ach_files SET status = 'applied', processed_at = now(), bank_response = $2 WHERE id = $1`, [
      file.id,
      JSON.stringify({ results }),
    ]);
    return { file: { ...file, status: 'applied' }, errors: [], results };
  });
}
